#include <iostream>
#include <map>
#include <utility>

using namespace std;

map<pair<int, int>, long long> all_memo;
map<tuple<int, int, int>, long long> limit_memo;
int n = 0, m = 0;

long long total_combinations(int low, int high) {
    if (low == high) {
        return 1;
    }
    pair<int, int> key = make_pair(low, high);
    if (all_memo.find(key) != all_memo.end()) {
        return all_memo[key];
    }
    all_memo[key] = 0;
    all_memo[key] += total_combinations(low + 1, high);
    all_memo[key] += total_combinations(low, high - 1);
    for (int i = low + 1; i < high; ++i) {
        all_memo[key] += total_combinations(low, i - 1) * total_combinations(i + 1, high);
    }
    return all_memo[key];
}

long long limit_combinations(int low, int high, int depth) {
    if (low == high) {
        return (depth < m) ? 1 : 0;
    }
    tuple<int, int, int> key = make_tuple(low, high, depth);
    if (limit_memo.find(key) != limit_memo.end()) {
        return limit_memo[key];
    }
    limit_memo[key] = 0;
    limit_memo[key] += limit_combinations(low + 1, high, depth + 1);
    limit_memo[key] += limit_combinations(low, high - 1, depth + 1);
    for (int i = low + 1; i < high; ++i) {
        limit_memo[key] += limit_combinations(low, i - 1, depth + 1) * limit_combinations(i + 1, high, depth + 1);
    }
    return limit_memo[key];
}

int main() {
    cin >> n >> m;
    long long answer = total_combinations(1, n) - limit_combinations(1, n, 1);
    cout << answer << endl;
    return 0;
}
